13	// recordFixNecessityReason は findings[].fix_necessity_reason を表し、E3 の 2 つの条件の
14	// 結果を持つ。goal_without_action は条件 1 (困る人は、何もしなくても目的を達成できるか)、
15	// workaround は条件 2 (困る人が気づいて取れる回避策があるか) の結果で、条件 1 が not-holds の
16	// ときだけ書く。必要度 (fix_necessity) はこの結果から決まる (fixNecessityFromReason)。
17	// 判定理由の文に書く形にしないのは、書き忘れを検査で見つけられないため (prior_defect と同じ)。
18	type recordFixNecessityReason struct {
19		GoalWithoutAction string `yaml:"goal_without_action"`
20		Workaround        string `yaml:"workaround"`
21		WorkaroundReason  string `yaml:"workaround_reason"`
22	}
23	
24	// recordBelowMinimumRef は findings[].below_minimum_ref を表す。D9 の (1) (前の回までの
25	// 下限未満の指摘と問題が同じ) が成り立った指摘に書く。run と finding は参照先 (1 始まりの
26	// 回番号と、その回の指摘の id)、line_check は D9 の (2) (対象の行が変わっていない) の結果。
27	type recordBelowMinimumRef struct {
28		Run        int    `yaml:"run"`
29		Finding    int    `yaml:"finding"`
30		LineCheck  string `yaml:"line_check"`
31		LineReason string `yaml:"line_reason"`
32	}
