34	// fixNecessityRank は必要度の高さを返す (must が最も高い)。列挙に無い値は 0。
35	func fixNecessityRank(v string) int {
36		switch v {
37		case "must":
38			return 3
39		case "should":
40			return 2
41		case "could":
42			return 1
43		}
44		return 0
45	}
46	
47	// fixNecessityJa は必要度を生成サマリに出す表記にする。
48	func fixNecessityJa(v string) string {
49		switch v {
50		case "must":
51			return "Must"
52		case "should":
53			return "Should"
54		case "could":
55			return "Could"
56		}
57		return recordCell(v)
58	}
59	
60	// fixNecessityBelow は、必要度が下限に満たないかを返す。下限が無ければ満たないことは無い。
61	// どちらかが列挙に無い値のときは、比べられないので偽を返す (列挙の誤りは別に報告する)。
62	func fixNecessityBelow(necessity, minimum string) bool {
63		n, m := fixNecessityRank(necessity), fixNecessityRank(minimum)
64		return n > 0 && m > 0 && n < m
65	}
66	
67	// fixNecessityFromReason は、2 つの条件の結果から決まる必要度を返す。どちらかの条件が
68	// undecided なら空 (必要度を付けない)。ok が偽なら、結果の形が誤っていて決まらない。
69	func fixNecessityFromReason(r *recordFixNecessityReason) (necessity string, ok bool) {
70		switch r.GoalWithoutAction {
71		case "holds":
72			return "could", r.Workaround == ""
73		case "undecided":
74			return "", r.Workaround == ""
75		case "not-holds":
76			switch r.Workaround {
77			case "holds":
78				return "should", true
79			case "not-holds":
80				return "must", true
81			case "undecided":
82				return "", true
83			}
84		}
85		return "", false
86	}
