88	// judgmentOmitted は、D9 で当たって判定を省略した指摘 (A3・B2) かを返す。
89	func judgmentOmitted(fd recordFinding) bool {
90		return fd.BelowMinimumRef != nil && fd.BelowMinimumRef.LineCheck == "holds"
91	}
