94	// 返す。無ければ -1。この回と、それより後の回では fix_necessity_reason を必須にする。
95	// 決め方と理由は recordPriorDefectFirstRun と同じ (過去の記録を書き換えさせずに通すため)。
96	func recordFixNecessityFirstRun(runs []recordRun) int {
97		for ri, run := range runs {
98			for _, fd := range run.Findings {
99				if fd.FixNecessityReason != nil {
100					return ri
101				}
102			}
103		}
104		return -1
105	}
