107	// recordFixNecessityProblems は、判定を省略していない指摘 1 件の必要度を検査する。
108	// 書く条件は E3 を行ったかで決まる。判定フローでは、D4 で根拠を確認した指摘
109	// (premise_check.result が verified) だけが E3 に進む。required が偽の回
110	// (recordFixNecessityFirstRun の回より前の回) では、無くても報告しない。
111	// minimum はその回の必要度の下限 (無ければ空)。
112	func recordFixNecessityProblems(required bool, minimum string, fd recordFinding) []string {
113		var problems []string
114		add := func(format string, args ...any) {
115			problems = append(problems, fmt.Sprintf(format, args...))
116		}
117		if fd.FixNecessity != "" && fixNecessityRank(fd.FixNecessity) == 0 {
118			add("fix_necessity は must / should / could のいずれか (決められなければ書かない): %q", fd.FixNecessity)
119		}
120		// 下限未満にできるのは、必要度を決めた指摘だけ。必要度の無い下限未満は、下の対応の
121		// 検査では見つからない (理由の無い指摘と、決められなかった指摘の両方がある) ので、ここで見る。
122		if fd.Verdict == "below_minimum" && fd.FixNecessity == "" {
123			add("verdict が below_minimum なのに fix_necessity がありません (下限未満にできるのは、必要度を決めた指摘だけ)")
124		}
125		verified := fd.PremiseCheck.Result == "verified"
126		r := fd.FixNecessityReason
127		if r == nil {
128			switch {
129			case fd.FixNecessity != "":
130				add("fix_necessity があるのに fix_necessity_reason がありません (必要度は、E3 の 2 つの条件の結果から決める)")
131			case verified && required:
132				add("fix_necessity_reason がありません (D4 で根拠を確認した指摘は E3 で必要度を判定するので、条件の結果を書く。この記録では、この回かそれより前の回で fix_necessity_reason を書いている)")
133			}
134			return problems
135		}
136		if !verified {
137			// E3 に進んでいない指摘の必要度は、どの値でも判定の経路と矛盾するので、中身は検査しない。
138			add("fix_necessity_reason は E3 を行った指摘 (premise_check.result が verified) にだけ書く (result %q)", fd.PremiseCheck.Result)
139			return problems
140		}
141		shapeValid := true
142		switch r.GoalWithoutAction {
143		case "holds", "not-holds", "undecided":
144		default:
145			shapeValid = false
146			add("fix_necessity_reason.goal_without_action は holds / not-holds / undecided のいずれか: %q", r.GoalWithoutAction)
147		}
148		switch {
149		case r.GoalWithoutAction == "not-holds":
150			switch r.Workaround {
151			case "holds", "not-holds", "undecided":
152			case "":
153				shapeValid = false
154				add("fix_necessity_reason.workaround がありません (goal_without_action が not-holds なら条件 2 を判定する)")
155			default:
156				shapeValid = false
157				add("fix_necessity_reason.workaround は holds / not-holds / undecided のいずれか: %q", r.Workaround)
158			}
159			if r.Workaround != "" && r.WorkaroundReason == "" {
160				add("fix_necessity_reason.workaround_reason がありません (回避策の手段か、無い理由か、決められなかった理由)")
161			}
162		case shapeValid:
163			// 条件 1 が成り立つか決められなければ、条件 2 は判定しない。
164			if r.Workaround != "" || r.WorkaroundReason != "" {
165				shapeValid = false
166				add("fix_necessity_reason.workaround と workaround_reason は、goal_without_action が not-holds のときだけ書く (goal_without_action %q)", r.GoalWithoutAction)
167			}
168		}
169		if !shapeValid {
170			return problems
171		}
172		want, _ := fixNecessityFromReason(r)
173		if fd.FixNecessity != want {
174			if want == "" {
175				add("fix_necessity_reason では必要度が決まらない (undecided がある) のに、fix_necessity %q があります", fd.FixNecessity)
176			} else {
177				add("fix_necessity は、fix_necessity_reason から決まる %s と違います: %q", want, fd.FixNecessity)
178			}
179			return problems
180		}
181		switch {
182		case want == "" && fd.Verdict == "adopted":
183			add("必要度を決められなかった (fix_necessity_reason に undecided がある) のに、verdict が adopted です (決められなければ H8 の保留)")
184		case fd.Verdict == "adopted" && fixNecessityBelow(want, minimum):
185			add("必要度 %s が回の下限 %s に満たないのに、verdict が adopted です (下限に満たなければ B1 の下限未満)", want, minimum)
186		case fd.Verdict == "below_minimum" && want != "" && !fixNecessityBelow(want, minimum):
187			if minimum == "" {
188				add("回に下限 (min_fix_necessity) が無いのに、verdict が below_minimum です")
189			} else {
190				add("必要度 %s が回の下限 %s 以上なのに、verdict が below_minimum です", want, minimum)
