196	// belowMinimumRefTarget は below_minimum_ref の参照先の指摘を返す。参照先にできるのは、
197	// この回 (添字 ri) より前の回の、必要度を判定して下限未満にした指摘 (B1) だけ。
198	// 判定を省略した指摘 (B2) は必要度を持たないので、参照先にしない。
199	func belowMinimumRefTarget(doc *recordDoc, ri int, ref *recordBelowMinimumRef) (*recordFinding, string) {
200		if ref.Run < 1 || ref.Run > ri {
