		}
		return problems
	}
	if !verified {
		// D8 に進んでいない指摘の D8 の結果は、どの値でも判定の経路と矛盾するので、中身は検査しない。
		add("prior_defect は D8 で判定した指摘 (premise_check.result が verified) にだけ書く (result %q)", fd.PremiseCheck.Result)
		return problems
	}
	lineValid := true
